const unitOptions=(selected,blank=false)=>options([...(blank?[['','Kies eenheid…']]:[]),...Object.entries(UNITS)],selected);
const currencyOptions=(selected,blank=false)=>options([...(blank?[['','Globale valuta']]:[]),...CURRENCIES.map(c=>[c,c])],selected);
const materialOptions=(selected,auto=true)=>options([...(auto?[['','Automatisch / niet bekend']]:[]),...Object.entries(MATERIALS).map(([k,v])=>[k,v.label]),['custom','Ander materiaal / eigen dichtheid']],selected);
const dimLabels={diameter:'Diameter (mm)',width:'Breedte / sleutelmaat (mm)',height:'Hoogte (mm)',thickness:'Dikte (mm)',wall:'Wanddikte (mm)',length:'Lengte per stuk (mm)',density:'Dichtheid (kg/m³)',kgm:'Gewicht (kg/m)',kgm2:'Gewicht (kg/m²)',piece:'Stukgewicht (kg)'};
